58	/**
59	 * @author Vitaliy Fedoriv
60	 */
61	
62	@RestController
63	@CrossOrigin(exposedHeaders = "errors, content-type")
64	@RequestMapping("/api")
65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    /** Minimal syntactic check for an email address: a non-empty local part, a single
68	     *  '@', and a dotted domain, none containing whitespace or a second '@'. */
69	    private static final Pattern EMAIL_PATTERN =
70	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
71	
72	    /** Dedicated audit logger; emits an audit line on successful owner create. */
73	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
74	
75	    private final ClinicService clinicService;
76	
77	    private final OwnerMapper ownerMapper;
78	
79	    private final PetMapper petMapper;
80	
81	    private final VisitMapper visitMapper;
82	
83	    private final TelephoneNormalizer telephoneNormalizer;
84	
85	    private final AddressNormalizer addressNormalizer;
86	
87	    public OwnerRestControllerV1(ClinicService clinicService,
88	                                 OwnerMapper ownerMapper,
89	                                 PetMapper petMapper,
90	                                 VisitMapper visitMapper,
91	                                 TelephoneNormalizer telephoneNormalizer,
92	                                 AddressNormalizer addressNormalizer) {
93	        this.clinicService = clinicService;
94	        this.ownerMapper = ownerMapper;
95	        this.petMapper = petMapper;
96	        this.visitMapper = visitMapper;
97	        this.telephoneNormalizer = telephoneNormalizer;
98	        this.addressNormalizer = addressNormalizer;
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
104	        Collection<Owner> owners;
105	        if (lastName != null) {
106	            owners = this.clinicService.findOwnerByLastName(lastName);
107	        } else {
108	            owners = this.clinicService.findAllOwners();
109	        }
110	        if (owners.isEmpty()) {
111	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
112	        }
113	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
119	        Owner owner = this.clinicService.findOwnerById(ownerId);
120	        if (owner == null) {
121	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
122	        }
123	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
124	    }
125	
126	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
127	    @Override
128	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
129	        HttpHeaders headers = new HttpHeaders();
130	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
131	        if (owner.getRegistrationDate() == null) {
132	            owner.setRegistrationDate(LocalDate.now());
133	        }
134	        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
135	        LocalDate registrationDate = owner.getRegistrationDate();
136	        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
137	            .map(Owner::getRegistrationDate)
138	            .filter(registrationDate::equals)
139	            .count();
140	        if (ownersCreatedThatDay >= 100) {
141	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
142	        }
143	        String address = addressNormalizer.normalize(owner.getAddress());
144	        if (address.isBlank()) {
145	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
146	        }
147	        owner.setAddress(address);
148	        String telephone = telephoneNormalizer.normalize(owner.getTelephone());
149	        if (telephone == null) {
150	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
151	        }
152	        owner.setTelephone(telephone);
153	        String email = owner.getEmail();
154	        if (email != null) {
155	            email = email.trim();
156	            if (!EMAIL_PATTERN.matcher(email).matches()) {
157	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
158	            }
159	            String emailKey = email.toLowerCase(Locale.ROOT);
160	            owner.setEmail(emailKey);
161	            boolean emailInUse = this.clinicService.findAllOwners().stream()
162	                .map(Owner::getEmail)
163	                .filter(Objects::nonNull)
164	                .map(existing -> existing.trim().toLowerCase(Locale.ROOT))
165	                .anyMatch(emailKey::equals);
166	            if (emailInUse) {
167	                return new ResponseEntity<>(HttpStatus.CONFLICT);
168	            }
169	        }
170	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
171	            .map(Owner::getTelephone)
172	            .filter(Objects::nonNull)
173	            .map(telephoneNormalizer::normalize)
174	            .anyMatch(telephone::equals);
175	        if (telephoneInUse) {
176	            return new ResponseEntity<>(HttpStatus.CONFLICT);
177	        }
178	        String cityKey = normalizeIdentity(owner.getCity());
179	        long ownersInCity = this.clinicService.findAllOwners().stream()
180	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(cityKey))
181	            .count();
182	        if (ownersInCity >= 50) {
183	            return new ResponseEntity<>(HttpStatus.CONFLICT);
184	        }
185	        String lastNameKey = normalizeIdentity(owner.getLastName());
186	        String addressKey = addressNormalizer.normalize(owner.getAddress());
187	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
188	            boolean householdDuplicate = this.clinicService.findAllOwners().stream()
189	                .anyMatch(existing -> normalizeIdentity(existing.getLastName()).equals(lastNameKey)
190	                    && addressNormalizer.normalize(existing.getAddress()).equals(addressKey));
191	            if (householdDuplicate) {
192	                return new ResponseEntity<>(HttpStatus.CONFLICT);
193	            }
194	        }
195	        owner.setHouseholdId(householdId(lastNameKey, addressKey));
196	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
197	        int namesakeCount = (int) this.clinicService.findAllOwners().stream()
198	            .filter(existing -> owner.getFirstName().equalsIgnoreCase(existing.getFirstName())
199	                && owner.getLastName().equalsIgnoreCase(existing.getLastName()))
200	            .count();
201	        owner.setNamesakeCount(namesakeCount);
202	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
203	        owner.setBulkSignupWarning(ownersCreatedThatDay > 80);
204	        this.clinicService.saveOwner(owner);
205	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
206	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
207	            ownerMapper.membershipLevel(owner));
208	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
209	        headers.setLocation(UriComponentsBuilder.newInstance()
210	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
211	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
212	    }
213	
214	    /**
215	     * Normalize a value for household-identity comparison: null becomes an empty
216	     * string, surrounding whitespace is trimmed, internal whitespace runs collapse
217	     * to a single space, and the result is lower-cased.
218	     */
219	    private static String normalizeIdentity(String value) {
220	        if (value == null) {
221	            return "";
222	        }
223	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
224	    }
225	
226	    /**
227	     * Build the stable, shared household identifier for an owner, formatted
228	     * {@code 'HH-<HEX12>'} where HEX12 is the first twelve upper-case hex characters
229	     * of the SHA-256 digest of the normalized lastName and address joined by '|'.
230	     * Owners in the same household (same normalized lastName and address) therefore
231	     * derive an identical householdId.
232	     */
233	    private static String householdId(String lastNameKey, String addressKey) {
234	        String source = lastNameKey + "|" + addressKey;
235	        try {
236	            byte[] digest = MessageDigest.getInstance("SHA-256")
237	                .digest(source.getBytes(StandardCharsets.UTF_8));
238	            StringBuilder sb = new StringBuilder(digest.length * 2);
239	            for (byte b : digest) {
240	                sb.append(String.format("%02x", b));
241	            }
242	            return "HH-" + sb.substring(0, 12).toUpperCase(Locale.ROOT);
243	        }
244	        catch (NoSuchAlgorithmException e) {
245	            throw new IllegalStateException("SHA-256 not available", e);
246	        }
247	    }
248	
249	    /**
250	     * Build the customer code assigned on create, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}:
251	     * CITY3 is the upper-cased first three letters of {@code city}, LAST3 is the upper-cased
252	     * first three letters of {@code lastName} and NNNN is a per-city 4-digit zero-padded
253	     * sequence equal to one more than the number of owners already in that city
254	     * (e.g. 'LON-SMI-0007').
255	     */
256	    private String nextCustomerCode(String city, String lastName) {
257	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
258	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
259	        String cityKey = normalizeIdentity(city);
260	        int sequence = (int) this.clinicService.findAllOwners().stream()
261	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(cityKey))
262	            .count() + 1;
263	        return String.format("%s-%s-%04d", city3, last3, sequence);
264	    }
265	
266	    /**
267	     * Roll a registration date forward to the next business day: a Saturday or Sunday
268	     * advances to the following Monday, and a weekday is returned unchanged.
269	     */
270	    private static LocalDate toBusinessDay(LocalDate date) {
271	        return switch (date.getDayOfWeek()) {
272	            case SATURDAY -> date.plusDays(2);
273	            case SUNDAY -> date.plusDays(1);
274	            default -> date;
275	        };
276	    }
277	
278	    /**
279	     * Build the membership number assigned on create, formatted
280	     * {@code '<customerCode>-M<YY>'} where YY is the last two digits of the
281	     * {@code registrationDate} year (e.g. 'LON-SMI-0007-M26').
282	     */
283	    private static String membershipNumber(String customerCode, LocalDate registrationDate) {
284	        String yy = String.format("%02d", registrationDate.getYear() % 100);
285	        return customerCode + "-M" + yy;
286	    }
287	
288	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
289	    @Override
290	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
291	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
292	        if (currentOwner == null) {
293	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
294	        }
295	        currentOwner.setAddress(ownerFieldsDto.getAddress());
296	        currentOwner.setCity(ownerFieldsDto.getCity());
297	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
298	        currentOwner.setLastName(ownerFieldsDto.getLastName());
299	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
300	        this.clinicService.saveOwner(currentOwner);
301	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
302	    }
303	
304	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
305	    @Transactional
306	    @Override
307	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
308	        Owner owner = this.clinicService.findOwnerById(ownerId);
309	        if (owner == null) {
310	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
311	        }
312	        this.clinicService.deleteOwner(owner);
313	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
314	    }
315	
316	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
317	    @Override
318	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
319	        Owner owner = this.clinicService.findOwnerById(ownerId);
320	        if (owner == null) {
321	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
322	        }
323	        HttpHeaders headers = new HttpHeaders();
324	        Pet pet = petMapper.toPet(petFieldsDto);
325	        owner.setId(ownerId);
326	        pet.setOwner(owner);
327	        pet.getType().setName(null);
328	        this.clinicService.savePet(pet);
329	        PetDto petDto = petMapper.toPetDto(pet);
330	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
331	            .buildAndExpand(pet.getId()).toUri());
332	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
333	    }
334	
335	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
336	    @Override
337	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
338	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
339	        if (currentOwner != null) {
340	            Pet currentPet = this.clinicService.findPetById(petId);
